// iconSVG is the `icon` template function. An icon the map does not carry is
// a build mistake, and the template error it raises says so on the page
// instead of drawing nothing.
func iconSVG(name string) (template.HTML, error) {
	body, ok := icons[name]
	if !ok {
		return "", errUnknownIcon(name)
	}
	// #nosec G203 -- the body is a compile-time literal from the map above
	return template.HTML(`<svg class="icon" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">` + body + `</svg>`), nil
}

type errUnknownIcon string

func (e errUnknownIcon) Error() string { return "no such icon: " + string(e) }
